// Gait clock advances only while walking, so pausing freezes the pose and resuming continues from it.
type TaskState = { walking: boolean };
const taskState: TaskState = { walking: true };
(window as unknown as { __TASK_STATE__: TaskState }).__TASK_STATE__ = taskState;
let gaitTime = 0;

window.addEventListener("keydown", (e) => {
  if (e.code === "Space" || e.key === " ") {
    e.preventDefault();
    if (!e.repeat) taskState.walking = !taskState.walking;
  }
});

app.onFrame((f) => {
  if (taskState.walking) gaitTime += f.dt;
  poseLegs(gaitTime);
});
